export const calcPopoverPosition = ({
  popoverEl,
  targetEl,
  angleEl,
  needsAngle,
  targetX,
  targetY,
  targetWidth = 0,
  targetHeight = 0,
  theme,
}) => {
  if (targetEl.current) {
    targetEl = targetEl.current;
  } else if (targetEl.value) {
    targetEl = targetEl.value;
  } else if (targetEl.el) {
    targetEl = targetEl.el;
  } else if (targetEl.$el) {
    targetEl = targetEl.$el;
  }

  if (typeof targetEl === 'string') {
    // eslint-disable-next-line
    targetEl = document.querySelector(targetEl);
  }

  /* eslint-disable */
  let appWidth = document.body.offsetWidth;
  let appHeight = document.body.offsetHeight;
  if (appWidth === 0) {
    appWidth = window.innerWidth;
  }
  if (appHeight === 0) {
    appHeight = window.innerHeight;
  }
  /* eslint-enable */
  const [popoverWidth, popoverHeight] = [
    popoverEl.offsetWidth,
    popoverEl.offsetHeight,
  ];
  let angleSize = 0;
  let angleLeft;
  let angleTop;
  let anglePosition = '';
  if (needsAngle) {
    angleSize = angleEl.offsetWidth / 2;
  }

  let targetOffsetLeft;
  let targetOffsetTop;
  let safeAreaTop = 0;
  let safeAreaLeft = 0;
  let safeAreaRight = 0;
  if (targetEl) {
    // eslint-disable-next-line
    const targetElStyles = window.getComputedStyle(targetEl);
    safeAreaTop =
      parseInt(targetElStyles.getPropertyValue('--c-safe-area-top'), 10) || 0;
    safeAreaLeft =
      parseInt(targetElStyles.getPropertyValue('--c-safe-area-left'), 10) || 0;
    safeAreaRight =
      parseInt(targetElStyles.getPropertyValue('--c-safe-area-right'), 10) || 0;
    if (Number.isNaN(safeAreaTop)) safeAreaTop = 0;
    if (Number.isNaN(safeAreaLeft)) safeAreaLeft = 0;
    if (Number.isNaN(safeAreaRight)) safeAreaRight = 0;
    targetWidth = targetEl.offsetWidth;
    targetHeight = targetEl.offsetHeight;

    const targetElBox = targetEl.getBoundingClientRect();
    targetOffsetLeft = targetElBox.left;
    targetOffsetTop = targetElBox.top;
  } else if (typeof targetX !== 'undefined' && targetY !== 'undefined') {
    targetOffsetLeft = targetX;
    targetOffsetTop = targetY;
  }

  let [left, top, diff] = [0, 0, 0];

  const angleMin = theme === 'ios' ? 13 : 23;

  // Top Position
  let position = 'top';

  if (popoverHeight + angleSize < targetOffsetTop - safeAreaTop) {
    // On top
    top = targetOffsetTop - popoverHeight - angleSize;
  } else if (
    popoverHeight + angleSize <
    appHeight - targetOffsetTop - targetHeight
  ) {
    // On bottom
    position = 'bottom';
    top = targetOffsetTop + targetHeight + angleSize;
  } else {
    // On middle
    position = 'middle';
    top = targetHeight / 2 + targetOffsetTop - popoverHeight / 2;
    diff = top;
    top = Math.max(5, Math.min(top, appHeight - popoverHeight - 5));
    diff -= top;
  }

  // Horizontal Position
  if (position === 'top' || position === 'bottom') {
    left = targetWidth / 2 + targetOffsetLeft - popoverWidth / 2;
    diff = left;
    left = Math.max(5, Math.min(left, appWidth - popoverWidth - 5));
    if (safeAreaLeft) {
      left = Math.max(left, safeAreaLeft);
    }
    if (safeAreaRight && left + popoverWidth > appWidth - 5 - safeAreaRight) {
      left = appWidth - 5 - safeAreaRight - popoverWidth;
    }
    if (position === 'top') {
      anglePosition = 'bottom';
    }
    if (position === 'bottom') {
      anglePosition = 'top';
    }
    diff -= left;
    angleLeft = popoverWidth / 2 - angleSize + diff;
    angleLeft = Math.max(
      Math.min(angleLeft, popoverWidth - angleSize * 2 - angleMin),
      angleMin
    );
  } else if (position === 'middle') {
    left = targetOffsetLeft - popoverWidth - angleSize;
    anglePosition = 'right';
    if (
      left < 5 ||
      left + popoverWidth + safeAreaRight > appWidth ||
      left < safeAreaLeft
    ) {
      if (left < 5) left = targetOffsetLeft + targetWidth + angleSize;
      if (left + popoverWidth + safeAreaRight > appWidth)
        left = appWidth - popoverWidth - 5 - safeAreaRight;
      if (left < safeAreaLeft) left = safeAreaLeft;
      anglePosition = 'left';
    }
    angleTop = popoverHeight / 2 - angleSize + diff;
    angleTop = Math.max(
      Math.min(angleTop, popoverHeight - angleSize * 2 - angleMin),
      angleMin
    );
  }

  const popoverVerticalPosition = position;
  const popoverHorizontalPosition = left < targetOffsetLeft ? 'left' : 'right';

  return {
    set: true,
    angleTop: typeof angleTop === 'undefined' ? undefined : `${angleTop}px`,
    angleLeft: typeof angleLeft === 'undefined' ? undefined : `${angleLeft}px`,
    anglePosition,
    popoverTop: `${top}px`,
    popoverLeft: `${left}px`,
    popoverPosition: `${popoverVerticalPosition}-${popoverHorizontalPosition}`,
  };
};

import { cls } from '../cls.js';

export const AccordionClasses = (props, colors, { className } = {}) => ({
  base: {
    common: cls('overflow-hidden', className),
    ios: cls('rounded-xl hairline', colors.bgIos),
    material: cls('rounded-2xl elevation-1', colors.bgMaterial),
  },
});

import { cls } from '../cls.js';

export const AccordionItemClasses = (props, colors, { className } = {}) => ({
  base: {
    common: cls(
      'flex items-center justify-between w-full px-4 py-3 text-left text-sm font-medium cursor-pointer',
      className,
    ),
    ios: cls('hairline-b last:hairline-b-0', colors.textIos, colors.activeIos),
    material: cls(colors.textMaterial, colors.activeMaterial),
  },
  chevron: {
    common: 'opacity-40 ms-2 shrink-0',
    ios: 'w-2 h-2',
    material: 'w-2 h-2',
  },
});

import { cls } from '../cls.js';

export const ActionsButtonClasses = (props, colors, darkClasses) => {
  const { fontSizeIos, fontSizeMaterial, bold, dividers } = props;
  return {
    base: {
      common: cls(
        `flex items-center w-full px-4 relative z-10 overflow-hidden`,
        dividers && 'hairline-b'
      ),
      ios: cls(
        `h-14`,
        colors.textIos,
        colors.bgIos,
        colors.activeBgIos,
        fontSizeIos,
        'first:rounded-t-xl last:rounded-b-xl justify-center',
        bold && 'font-semibold'
      ),
      material: cls(
        `h-12`,
        colors.textMaterial,
        colors.bgMaterial,
        colors.activeBgMaterial,
        fontSizeMaterial,
        'justify-start',
        darkClasses('dark:touch-ripple-white'),
        bold && 'font-medium'
      ),
    },
  };
};

import { cls } from '../cls.js';
import { positionClass } from '../position-class.js';

export const ActionsClasses = (props, classes) => {
  return {
    base: {
      common: cls(
        'transition-transform z-40 left-1/2 bottom-0 transform -translate-x-1/2 max-w-md w-full overflow-hidden',
        positionClass('fixed', classes)
      ),
      ios: 'pt-2 px-2 pb-2-safe duration-300',
      material:
        'pb-safe last-child-hairline-b-none rounded-t-2xl duration-400 ease-material-in',
      opened: '',
      closed: 'translate-y-full',
    },
    backdrop: {
      common:
        'fixed z-40 w-full h-full left-0 top-0 bg-black bg-opacity-50 duration-300',
      opened: '',
      closed: 'opacity-0 pointer-events-none',
    },
  };
};

import { cls } from '../cls.js';

// eslint-disable-next-line
export const ActionsGroupClasses = (props) => {
  const { dividers } = props;
  return {
    base: {
      common: `relative`,
      ios: `mt-2 first:mt-0 last-child-hairline-b-none`,
      material: cls(dividers && `hairline-b`),
    },
  };
};

import { cls } from '../cls.js';

export const ActionsLabelClasses = (props, colors) => {
  const { fontSizeIos, fontSizeMaterial, dividers } = props;
  return {
    base: {
      common: cls(
        `flex items-center w-full px-4 relative z-10 overflow-hidden ${colors.activeBg}`,
        dividers && 'hairline-b'
      ),
      ios: cls(
        `h-14`,
        colors.bgIos,
        colors.textIos,
        fontSizeIos,
        'first:rounded-t-xl last:rounded-b-xl justify-center'
      ),
      material: cls(
        `h-12`,
        colors.bgMaterial,
        colors.textMaterial,
        fontSizeMaterial,
        'font-medium',
        'justify-start'
      ),
    },
  };
};

import { cls } from '../cls.js';

export const AlertClasses = (props, colors, { className } = {}) => ({
  base: {
    common: cls('px-4 py-3 text-sm font-medium mb-2', className),
    ios: cls('rounded-xl', colors.bgIos, colors.textIos),
    material: cls('rounded-lg elevation-1', colors.bgMaterial, colors.textMaterial),
  },
});

import { cls } from '../cls.js';
import { positionClass } from '../position-class.js';

export const AppClasses = (props, currentTheme, classes) => {
  const { safeAreas } = props;
  return cls(
    currentTheme === 'ios' && `c-ios`,
    currentTheme === 'material' && 'c-material',
    'c-app w-full h-full min-h-screen',
    safeAreas && 'safe-areas',
    positionClass('relative', classes),
    classes
  );
};

import { cls } from '../cls.js';

export const AvatarClasses = (props, colors, { className } = {}) => ({
  base: {
    common: cls(
      'inline-flex items-center justify-center font-semibold shrink-0 select-none',
      className,
    ),
    ios: cls('w-12 h-12 text-base rounded-full', colors.bgIos, colors.textIos),
    material: cls(
      'w-10 h-10 text-sm rounded-full',
      colors.bgMaterial,
      colors.textMaterial,
    ),
  },
});

export const BadgeClasses = (props, colors) => {
  return {
    base: {
      common: `${colors.text} ${colors.bg} inline-flex items-center justify-center rounded-full leading-none`,
      ios: `font-semibold`,
      material: `font-medium`,
      sm: 'text-2xs min-w-4 min-h-4 px-0.5',
      md: 'text-xs min-w-5 min-h-5 px-1.5 py-0.5',
    },
  };
};

import { cls } from '../cls.js';
import { positionClass } from '../position-class.js';

export const BlockClasses = (props, colors, classes) => {
  const { inset, nested, margin, padding, strong, outline } = props;
  return {
    base: {
      common: cls(
        `text-sm z-10`,
        positionClass('relative', classes),
        !inset && !nested && outline && 'hairline-t hairline-b',
        inset && outline && 'border',
        inset && 'px-4',
        !inset && 'pl-4-safe pr-4-safe',
        !nested && margin,
        (strong || outline) && padding
      ),
      ios: cls(
        colors.textIos,
        strong && colors.strongBgIos,
        inset && outline && colors.outlineIos
      ),
      material: cls(
        colors.textMaterial,
        strong && colors.strongBgMaterial,
        inset && outline && colors.outlineMaterial
      ),
    },
    inset: {
      common: `ml-4-safe mr-4-safe overflow-hidden`,
      ios: `rounded-lg`,
      material: `rounded-2xl`,
    },
  };
};

import { cls } from '../cls.js';

export const BlockFooterClasses = (props, colors) => {
  const { inset } = props;
  return {
    base: {
      common: cls(
        `mb-8 flex items-center -mt-6 text-sm`,
        inset ? 'pl-8-safe pr-8-safe' : 'pl-4-safe pr-4-safe'
      ),
      ios: colors.textIos,
      material: colors.textMaterial,
    },
  };
};

import { cls } from '../cls.js';

export const BlockHeaderClasses = (props, colors) => {
  const { inset } = props;
  return {
    base: {
      common: cls(
        `mt-8 flex items-center -mb-6 text-sm`,
        inset ? 'pl-8-safe pr-8-safe' : 'pl-4-safe pr-4-safe'
      ),
      ios: colors.textIos,
      material: colors.textMaterial,
    },
  };
};

import { cls } from '../cls.js';

export const BlockTitleClasses = (props, colors) => {
  const { withBlock, medium, large } = props;
  return {
    base: {
      common: withBlock
        ? 'pl-4-safe pr-4-safe mt-8 -mb-6 flex justify-between items-center'
        : 'block w-full mb-3 mt-0',
      ios: cls(
        `font-semibold ${colors.textIos}`,
        large && 'text-[1.5rem]',
        medium && 'text-[1.125rem]',
        !medium && !large && 'text-[1rem]'
      ),
      material: cls(
        `font-medium ${colors.textMaterial}`,
        large && 'text-[1.375rem]',
        medium && 'text-[1rem]',
        !medium && !large && 'text-[0.875rem]'
      ),
    },
  };
};

export const BreadcrumbsClasses = (props) => {
  const { fontSizeIos, fontSizeMaterial } = props;
  return {
    base: {
      common: `flex items-center justify-start overflow-auto whitespace-nowrap py-1 px-0 space-x-3 no-scrollbar rtl:space-x-reverse`,
      ios: fontSizeIos,
      material: fontSizeMaterial,
    },
  };
};

import { cls } from '../cls.js';

export const BreadcrumbsCollapsedClasses = (props, colors) => {
  return {
    base: {
      common: `flex items-center cursor-pointer space-x-0.75 rtl:space-x-reverse ${colors.bg}`,
      ios: cls(
        `rounded active:opacity-30 px-1.5 h-[1em] duration-300 active:duration-0`,
        colors.bgIos
      ),
      material: cls('py-3 px-2 rounded-lg', colors.bgMaterial),
    },
    dot: {
      common: `w-1 h-1 rounded-full ${colors.dotBg}`,
      ios: colors.dotBgIos,
      material: colors.dotBgMaterial,
    },
  };
};

import { cls } from '../cls.js';

export const BreadcrumbsItemClasses = (props, colors) => {
  const { active } = props;
  return {
    base: {
      common: cls(`flex items-center overflow-hidden`),
      ios: cls(
        colors.textIos,
        colors.bgIos,
        active ? colors.textActiveIos : colors.textIos,
        active && 'font-semibold'
      ),
      material: cls(
        `font-medium px-2 py-1 rounded-lg`,
        colors.bgMaterial,
        active ? colors.textActiveMaterial : colors.textMaterial
      ),
    },
  };
};

export const BreadcrumbsSeparatorClasses = () => {
  return {
    base: {
      common: `w-3 opacity-35 flex justify-center`,
      ios: ``,
      material: ``,
    },
    icon: {
      common: 'rtl:rotate-180',
      ios: 'h-3',
      material: 'h-2.5',
    },
  };
};

import { positionClass } from '../position-class.js';
import { cls } from '../cls.js';

export const ButtonClasses = (props, colors, classes, darkClasses) => {
  const { inline, segmented, segmentedStrong, segmentedActive, disabled } =
    props;
  return {
    base: {
      common: cls(
        'flex text-center justify-center items-center appearance-none py-1 transition-colors focus:outline-none cursor-pointer select-none overflow-hidden z-10',
        inline ? 'inline-flex' : 'w-full flex',
        positionClass('relative', classes),
        disabled && 'pointer-events-none',
        segmentedStrong && segmentedActive && 'c-segmented-strong-button-active'
      ),
      ios: `uppercase duration-100 font-semibold px-2`,
      material: `duration-300 font-medium px-4`,

      square: {
        ios:
          segmented && !segmentedStrong
            ? 'first:rounded-s last:rounded-e'
            : 'rounded',
        material:
          segmented && !segmentedStrong
            ? 'first:rounded-lg-s last:rounded-lg-e'
            : 'rounded-lg',
      },

      rounded: segmented && !segmentedStrong ? '' : 'rounded-full',
    },
    style: {
      fill: {
        common: cls(disabled && cls(colors.disabledBg, colors.disabledText)),
        ios: cls(
          disabled
            ? cls(colors.disabledBg, colors.disabledText)
            : `${colors.fillTextIos} ${colors.fillBgIos} ${colors.fillActiveBgIos}`
        ),
        material: cls(
          disabled
            ? cls(colors.disabledBg, colors.disabledText)
            : cls(
                colors.fillTextMaterial,
                colors.fillBgMaterial,
                colors.fillActiveBgMaterial,
                colors.fillTouchRipple
              )
        ),
      },
      outline: {
        common: cls(
          disabled
            ? cls(colors.disabledText, colors.disabledBorder)
            : cls('active:bg-opacity-15', colors.touchRipple)
        ),
        ios: cls(
          !segmented && 'border-2',
          !disabled && !segmented && colors.outlineBorderIos,
          !disabled && cls(colors.textIos, colors.activeBgIos)
        ),
        material: cls(
          !segmented && 'border',
          !disabled && !segmented && colors.outlineBorderMaterial,
          !disabled && cls(colors.textMaterial, colors.activeBgMaterial)
        ),
      },
      clear: {
        common: cls(
          disabled
            ? colors.disabledText
            : `active:bg-opacity-15 ${colors.touchRipple}`
        ),
        ios: !disabled && cls(colors.textIos, colors.activeBgIos),
        material:
          !disabled && cls(colors.textMaterial, colors.activeBgMaterial),
      },
      tonal: {
        common: disabled
          ? cls(colors.disabledBg, colors.disabledText)
          : cls(colors.touchRipple),
        ios:
          !disabled &&
          cls(
            colors.tonalTextIos,
            colors.tonalBgIos,
            colors.activeBgIos,
            'bg-opacity-15 active:bg-opacity-25'
          ),
        material:
          !disabled &&
          cls(
            colors.tonalTextMaterial,
            colors.tonalBgMaterial,
            colors.activeBgMaterial
          ),
      },
      segmentedStrong: {
        common: cls(
          '!bg-transparent shadow-none text-primary relative z-0',
          darkClasses('dark:text-white/55'),
          `active:bg-black active:bg-opacity-10`,
          darkClasses(
            'dark:active:bg-white dark:active:bg-opacity-10 dark:touch-ripple-white'
          ),
          colors.touchRipple
        ),
        ios: cls(
          !disabled && colors.textIos,
          darkClasses('dark:text-white/55')
        ),
        material: cls(
          !disabled && colors.textMaterial,
          darkClasses('dark:text-white/55')
        ),
      },
      segmentedStrongActive: {
        common: 'duration-0 relative z-10 bg-transparent shadow-none',
        ios: cls(
          !disabled && 'text-black',
          darkClasses('dark:text-white')
        ),
        material: cls(
          !disabled && 'text-black',
          darkClasses('dark:text-white')
        ),
      },
    },
    size: {
      small: {
        ios: `text-xs h-7`,
        material: `text-sm h-8`,
      },
      medium: {
        common: 'text-sm',
        ios: `h-7`,
        material: `h-10`,
      },
      large: {
        ios: `h-11`,
        material: `h-12`,
      },
    },
    raised: `shadow active:shadow-lg`,
  };
};

import { cls } from '../cls.js';

export const CardClasses = (props, colors) => {
  const { margin, headerDivider, footerDivider, contentWrapPadding } = props;
  return {
    base: {
      common: cls(margin, `overflow-hidden`),
      ios: cls('rounded-lg', colors.bgIos, colors.textIos),
      material: cls('rounded-2xl', colors.bgMaterial, colors.textMaterial),
      plain: '',
      raised: 'shadow',
      outline: {
        common: cls(`border`),
        ios: colors.outlineIos,
        material: colors.outlineMaterial,
      },
    },
    header: {
      common: cls(headerDivider && `border-b`, `p-4`),
      ios: cls(headerDivider && colors.outlineIos, props.headerFontSizeIos),
      material: cls(
        headerDivider && colors.outlineMaterial,
        props.headerFontSizeMaterial
      ),
    },
    content: cls(contentWrapPadding, 'text-sm'),
    footer: {
      common: cls(headerDivider && `border-t`, `text-sm p-4`),
      ios: cls(colors.footerTextIos, footerDivider && colors.outlineIos),
      material: cls(
        colors.footerTextMaterial,
        footerDivider && colors.outlineMaterial
      ),
    },
  };
};

import { cls } from '../cls.js';
import { positionClass } from '../position-class.js';

export const CheckboxClasses = (props, colors, classes, darkClasses) => {
  return {
    base: cls(
      `cursor-pointer inline-flex align-middle`,
      positionClass('relative', classes),
      darkClasses('dark:touch-ripple-white')
    ),
    iconWrap: {
      common: cls(
        `flex items-center justify-center text-white`,
        darkClasses('dark:text-black')
      ),
      ios: 'w-5.5 h-5.5 rounded-full border',
      material: 'w-4.5 h-4.5 rounded-sm border-2',
      notChecked: {
        ios: colors.borderIos,
        material: colors.borderMaterial,
      },
      checked: {
        ios: `${colors.bgCheckedIos} ${colors.borderCheckedIos}`,
        material: `${colors.bgCheckedMaterial} ${colors.borderCheckedMaterial}`,
      },
    },
    icon: {
      notChecked: 'opacity-0',
      checked: 'opacity-100',
    },
    indeterminateIcon: {
      common: cls(`bg-white w-3/4`, darkClasses('dark:bg-black')),
      ios: 'h-0.5 rounded-full',
      material: 'h-0.5',
    },
    input: 'hidden',
  };
};

import { cls } from '../cls.js';

export const ChipClasses = (props, colors) => {
  return {
    base: {
      common: `text-sm inline-flex items-center justify-center align-middle rounded-full px-3`,
      ios: 'rounded-full h-7',
      material: 'rounded-lg h-8 font-medium',
      fill: {
        ios: cls(
          colors.fillBg || colors.fillBgIos,
          colors.fillText || colors.fillTextIos
        ),
        material: cls(
          colors.fillBg || colors.fillBgMaterial,
          colors.fillText || colors.fillTextMaterial
        ),
      },
      outline: {
        common: `border`,
        ios: cls(
          colors.outlineText || colors.outlineTextIos,
          colors.outlineBorder || colors.outlineBorderIos
        ),
        material: cls(
          colors.outlineText || colors.outlineTextMaterial,
          colors.outlineBorder || colors.outlineBorderMaterial
        ),
      },
    },
    media: {
      common: '-my-1 me-1 select-none',
      ios: '-ms-3',
      material: '-ms-2',
    },
    deleteButton:
      '-me-2 -my-1 ms-1 h-full flex items-center justify-center w-6 cursor-pointer opacity-50 active:opacity-100 select-none',
  };
};

import { cls } from '../cls.js';

export const DatetimeClasses = (props, colors, { className } = {}) => ({
  base: {
    common: cls('px-4 py-3 text-sm mb-2', className),
    ios: cls('rounded-xl', colors.bgIos, colors.textIos),
    material: cls('rounded-lg', colors.bgMaterial, colors.textMaterial),
  },
});

import { cls } from '../cls.js';

export const DialogButtonClasses = (props, colors) => {
  const { strong, disabled } = props;
  return {
    base: {
      ios: cls(
        'text-center text-[17px] flex items-center justify-center h-11 w-full hairline-r rtl:hairline-l relative first:rounded-bl-xl last:rounded-br-xl rtl:first:rounded-br-xl rtl:first:rounded-bl-none rtl:last:rounded-bl-xl rtl:last:rounded-br-none',
        disabled ? colors.disabledTextIos : colors.textIos,
        strong && 'font-semibold',
        !disabled && colors.activeBgIos
      ),
    },
  };
};

import { cls } from '../cls.js';
import { positionClass } from '../position-class.js';

export const DialogClasses = (props, colors, classes, { hasButtons }) => {
  const {
    titleFontSizeMaterial,
    titleFontSizeIos,
    translucent,
    sizeIos,
    sizeMaterial,
  } = props;
  return {
    base: {
      common: cls(
        'left-1/2 top-1/2 transform -translate-x-1/2 -translate-y-1/2 z-40 max-h-full overflow-hidden duration-400',
        positionClass('fixed', classes)
      ),
      ios: cls(
        'rounded-xl max-w-full',
