export function filterColors(obj) {
  if (!obj || typeof obj !== 'object') {
    return {};
  }

  const filtered = {};
  Object.keys(obj).forEach((key) => {
    if (obj[key] != null) {
      filtered[key] = obj[key];
    }
  });
  return filtered;
}

export const positionClass = (position, className = '') => {
  if (!className || typeof className !== 'string') return position;
  const classes = ['static', 'relative', 'absolute', 'fixed', 'sticky'];
  const hasPositionClass =
    classes.filter((c) => className.indexOf(c) >= 0).length > 0;
  return hasPositionClass ? '' : position;
};

export class TouchRipple {
  constructor(el, x, y) {
    const ripple = this;

    if (!el) return undefined;
    ripple.el = el;

    const { left, top, width, height } = el.getBoundingClientRect();
    const center = {
      x: x - left,
      y: y - top,
    };
    let diameter = Math.max((height ** 2 + width ** 2) ** 0.5, 48);

    const isInset = el.classList.contains('c-touch-ripple-inset');

    if (isInset) {
      diameter = Math.max(Math.min(width, height), 48);
    }

    /* eslint-disable no-restricted-globals */
    const isOverflowHidden =
      typeof window !== 'undefined' &&
      window.getComputedStyle(el, null).getPropertyValue('overflow') ===
        'hidden';

    /* eslint-enable no-restricted-globals */
    if (!isInset && isOverflowHidden) {
      const distanceFromCenter =
        ((center.x - width / 2) ** 2 + (center.y - height / 2) ** 2) ** 0.5;
      const scale = (diameter / 2 + distanceFromCenter) / (diameter / 2);
      ripple.rippleTransform = `translate3d(0px, 0px, 0) scale(${scale})`;
    } else {
      // prettier-ignore
      ripple.rippleTransform = `translate3d(${-center.x + width / 2}px, ${-center.y + height / 2}px, 0) scale(1)`;
    }

    // eslint-disable-next-line
    ripple.rippleWaveEl = document.createElement('span');
    ripple.rippleWaveEl.classList.add('c-touch-ripple-wave');
    ripple.rippleWaveEl.setAttribute('hidden', '');

    ripple.rippleWaveEl.style = `
      width: ${diameter}px;
      height: ${diameter}px;
      margin-top:-${diameter / 2}px;
      margin-left:-${diameter / 2}px;
      left:${center.x}px;
      top:${center.y}px; --c-ripple-transform: ${ripple.rippleTransform}`;

    el.insertAdjacentElement('afterbegin', ripple.rippleWaveEl);

    const animationEnd = () => {
      ripple.rippleWaveEl.removeEventListener('animationend', animationEnd);
      if (!ripple.rippleWaveEl) return;
      if (ripple.rippleWaveEl.classList.contains('c-touch-ripple-wave-out'))
        return;
      ripple.rippleWaveEl.classList.add('c-touch-ripple-wave-in');
      if (ripple.shouldBeRemoved) {
        ripple.out();
      }
    };
    ripple.rippleWaveEl.addEventListener('animationend', animationEnd);

    return ripple;
  }

  destroy() {
    let ripple = this;
    if (ripple.rippleWaveEl) {
      ripple.el.removeChild(ripple.rippleWaveEl);
    }
    Object.keys(ripple).forEach((key) => {
      ripple[key] = null;
      delete ripple[key];
    });
    ripple = null;
  }

  out() {
    const ripple = this;
    const { rippleWaveEl } = this;
    clearTimeout(ripple.removeTimeout);
    rippleWaveEl.classList.add('c-touch-ripple-wave-out');

    ripple.removeTimeout = setTimeout(() => {
      ripple.destroy();
    }, 300);
    const animationEnd = () => {
      ripple.rippleWaveEl.removeEventListener('animationend', animationEnd);
      clearTimeout(ripple.removeTimeout);
      ripple.destroy();
    };
    ripple.rippleWaveEl.addEventListener('animationend', animationEnd);
  }

  remove() {
    const ripple = this;
    if (ripple.shouldBeRemoved) return;
    ripple.removeTimeout = setTimeout(() => {
      ripple.destroy();
    }, 400);
    ripple.shouldBeRemoved = true;
    if (ripple.rippleWaveEl.classList.contains('c-touch-ripple-wave-in')) {
      ripple.out();
    }
  }
}

const nextTick = (fn) => {
  requestAnimationFrame(() => {
    requestAnimationFrame(fn);
  });
};

export const useIosHighlight = ({
  getEl,
  zIndex = 10,
  opacity = 1,
  offset = 1,
  enabled = true,
  data = {},
}) => {
  const isEnabled = () => {
    if (typeof enabled === 'function') {
      return enabled();
    }
    return enabled;
  };
  const removeHoverHighlight = () => {
    const el = getEl();
    if (el && data.elScale) {
      data.elScale = false;
      el.style.scale = '';

      const onTransitionEnd = () => {
        el.style.transitionDuration = '';
        el.style.transitionTimingFunction = '';
        el.removeEventListener('transitionend', onTransitionEnd);
      };
      el.addEventListener('transitionend', onTransitionEnd);
    }

    if (data.lightElWrap) {
      const lightElWrap = data.lightElWrap;
      if (lightElWrap.style.opacity === '0') {
        lightElWrap.remove();
      } else {
        lightElWrap.addEventListener('transitionend', () => {
          lightElWrap.remove();
        });
        lightElWrap.style.opacity = 0;
      }
    }
  };

  const setLightPosition = (e) => {
    if (data.lightEl) {
      const { x, y } = e;
      const offsetX = x - data.rect.x;
      const offsetY = y - data.rect.y;
      data.lightEl.style.transform = `translate3d(${offsetX}px, ${offsetY}px, 0)`;
    }
  };

  const onPointerEnter = (e) => {
    if (!isEnabled()) return;
    const d = data;
    const el = getEl();

    d.rect = el.getBoundingClientRect();
    const lightElWrap = document.createElement('span');
    lightElWrap.className = 'rounded-[inherit]';
    lightElWrap.style = `left: ${offset}px; top: ${offset}px; right: ${offset}px; bottom: ${offset}px;transition-duration: 300ms; opacity: 0; position: absolute; overflow: hidden; pointer-events: none`;
    const lightEl = document.createElement('span');
    const { width, height } = d.rect;
    const radius = (width ** 2 + height ** 2) ** 0.5;
    lightEl.style.position = `absolute`;
    lightEl.style.zIndex = zIndex;
    lightEl.style.width = `${radius * 2}px`;
    lightEl.style.left = `${-radius}px`;
    lightEl.style.height = `${radius * 2}px`;
    lightEl.style.top = `${-radius}px`;
    lightEl.style.borderRadius = `50%`;
    const lightColor = 'var(--color-ios-hover-highlight)';

    lightEl.style.backgroundImage = `radial-gradient(circle at center, color-mix(in oklab, ${lightColor} ${opacity * 100}%, transparent), transparent 50%)`;

    lightEl.style.pointerEvents = 'none';
    d.lightEl = lightEl;
    d.lightElWrap = lightElWrap;
    setLightPosition(e);
    lightElWrap.append(lightEl);
    el.append(lightElWrap);
    if (e.pointerType !== 'mouse') {
      if (e.pointerType !== 'mouse') {
        d.elScale = true;
        let scale = 1.25;
        if (d.rect.width > 60 || d.rect.height > 60) {
          scale = 1.05;
        }
        el.style.scale = scale;
        el.style.transitionDuration = '300ms';
        el.style.transitionTimingFunction = 'ease-in-out';
      }
    }
    nextTick(() => {
      lightElWrap.style.opacity = 1;
    });
  };

  const onPointerMove = (e) => {
    if (!isEnabled()) return;
    setLightPosition(e);
  };
  const onPointerLeave = (e) => {
    removeHoverHighlight();
  };
  const attachEvents = () => {
    const el = getEl();
    if (!el) return;
    el.addEventListener('pointerenter', onPointerEnter);
    el.addEventListener('pointermove', onPointerMove);
    el.addEventListener('pointerleave', onPointerLeave);
  };
  const detachEvents = () => {
    const el = getEl();
    if (!el) return;
    el.removeEventListener('pointerenter', onPointerEnter);
    el.removeEventListener('pointermove', onPointerMove);
    el.removeEventListener('pointerleave', onPointerLeave);
  };

  return {
    removeHoverHighlight,
    attachEvents,
    detachEvents,
  };
};
